CREATE OR REPLACE FUNCTION app.can_write_appointment(p_workspace_id uuid, p_professional_member_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
DECLARE
  v_actor public.workspace_members;
BEGIN
  SELECT m.* INTO v_actor
  FROM public.workspace_members m
  WHERE m.workspace_id = p_workspace_id
    AND m.user_id = auth.uid()
    AND m.status = 'active';
  IF v_actor.id IS NULL THEN
    RETURN false;
  END IF;
  IF v_actor.role IN (
    'owner'::public.member_role,
    'admin'::public.member_role,
    'receptionist'::public.member_role
  ) THEN
    RETURN true;
  END IF;
  RETURN v_actor.role = 'professional'::public.member_role
    AND v_actor.id = p_professional_member_id;
END;
$function$

CREATE OR REPLACE FUNCTION app.create_appointment(p_workspace_id uuid, p_client_id uuid, p_professional_member_id uuid, p_service_id uuid, p_starts_at timestamp with time zone, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_actor public.workspace_members;
  v_snapshot record;
  v_ends timestamptz;
  v_notes text;
  v_id uuid;
  v_client_archived timestamptz;
BEGIN
  PERFORM app.require_confirmed_email();
  v_actor := app.actor_member(p_workspace_id);

  IF NOT app.can_write_appointment(p_workspace_id, p_professional_member_id) THEN
    RAISE EXCEPTION 'appointment_write_denied' USING ERRCODE = '42501';
  END IF;

  SELECT c.archived_at INTO v_client_archived
  FROM public.workspace_clients c
  WHERE c.id = p_client_id
    AND c.workspace_id = p_workspace_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'client_not_found' USING ERRCODE = '22023';
  END IF;
  IF v_client_archived IS NOT NULL THEN
    RAISE EXCEPTION 'client_archived' USING ERRCODE = '22023';
  END IF;

  PERFORM app.lock_professional_agenda(p_professional_member_id);

  SELECT s.price_cents, s.duration_minutes
    INTO v_snapshot
  FROM app.resolve_service_snapshot(p_workspace_id, p_professional_member_id, p_service_id) s;

  v_ends := p_starts_at + make_interval(mins => v_snapshot.duration_minutes);
  v_notes := nullif(btrim(COALESCE(p_notes, '')), '');

  PERFORM app.assert_slot_available(
    p_workspace_id,
    p_professional_member_id,
    p_starts_at,
    v_ends,
    NULL
  );

  INSERT INTO public.appointments (
    workspace_id,
    client_id,
    professional_member_id,
    service_id,
    starts_at,
    ends_at,
    status,
    price_cents,
    duration_minutes,
    notes,
    created_by
  ) VALUES (
    p_workspace_id,
    p_client_id,
    p_professional_member_id,
    p_service_id,
    p_starts_at,
    v_ends,
    'scheduled'::public.appointment_status,
    v_snapshot.price_cents,
    v_snapshot.duration_minutes,
    v_notes,
    auth.uid()
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$function$

CREATE OR REPLACE FUNCTION app.create_public_appointment(p_slug text, p_service_id uuid, p_professional_member_id uuid, p_starts_at timestamp with time zone, p_full_name text, p_phone text, p_email text, p_customer_note text DEFAULT NULL::text, p_ip_hash text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_ws uuid;
  v_pro uuid;
  v_client uuid;
  v_snapshot record;
  v_ends timestamptz;
  v_note text;
  v_id uuid;
  v_uid uuid := auth.uid();
  v_email text := nullif(lower(btrim(COALESCE(p_email, ''))), '');
  v_phone text;
  v_confirmed boolean := false;
  v_ws_name text;
  v_slug text;
  v_service_name text;
  v_pro_name text;
  v_phone_biz text;
  v_tz text;
BEGIN
  v_ws := app.resolve_public_workspace(p_slug);
  v_tz := app.workspace_timezone(v_ws);
  v_phone := app.normalize_phone(p_phone);
  IF v_phone IS NULL THEN
    RAISE EXCEPTION 'invalid_phone' USING ERRCODE = '22023';
  END IF;
  IF v_email IS NULL THEN
    RAISE EXCEPTION 'invalid_email' USING ERRCODE = '22023';
  END IF;

  IF v_uid IS NOT NULL THEN
    SELECT u.email_confirmed_at IS NOT NULL INTO v_confirmed
    FROM auth.users u WHERE u.id = v_uid;
    IF NOT COALESCE(v_confirmed, false) THEN
      v_uid := NULL;
    END IF;
  END IF;

  PERFORM app.assert_public_booking_rate(v_ws, v_email, v_phone, nullif(btrim(COALESCE(p_ip_hash, '')), ''));
  PERFORM app.assert_public_booking_window(v_ws, p_starts_at);

  v_pro := app.pick_professional_for_slot(v_ws, p_service_id, p_starts_at, p_professional_member_id);

  SELECT s.price_cents, s.duration_minutes
    INTO v_snapshot
  FROM app.resolve_service_snapshot(v_ws, v_pro, p_service_id) s;

  v_ends := p_starts_at + make_interval(mins => v_snapshot.duration_minutes);
  v_note := nullif(btrim(COALESCE(p_customer_note, '')), '');
  IF v_note IS NOT NULL AND char_length(v_note) > 500 THEN
    RAISE EXCEPTION 'customer_note_too_long' USING ERRCODE = '22023';
  END IF;

  v_client := app.find_or_create_public_client(
    v_ws,
    p_full_name,
    v_email,
    v_phone,
    v_uid
  );

  PERFORM app.lock_professional_agenda(v_pro);

  BEGIN
    PERFORM app.assert_slot_available(v_ws, v_pro, p_starts_at, v_ends, NULL);
  EXCEPTION
    WHEN SQLSTATE '23P01' THEN
      RAISE EXCEPTION 'slot_taken' USING ERRCODE = '23P01';
  END;

  BEGIN
    INSERT INTO public.appointments (
      workspace_id,
      client_id,
      professional_member_id,
      service_id,
      starts_at,
      ends_at,
      status,
      price_cents,
      duration_minutes,
      customer_note,
      created_by
    ) VALUES (
      v_ws,
      v_client,
      v_pro,
      p_service_id,
      p_starts_at,
      v_ends,
      'scheduled'::public.appointment_status,
      v_snapshot.price_cents,
      v_snapshot.duration_minutes,
      v_note,
      v_uid
    )
    RETURNING id INTO v_id;
  EXCEPTION
    WHEN exclusion_violation OR SQLSTATE '23P01' THEN
      RAISE EXCEPTION 'slot_taken' USING ERRCODE = '23P01';
  END;

  INSERT INTO public.public_booking_rate_events (workspace_id, email, phone, ip_hash)
  VALUES (v_ws, v_email, v_phone, nullif(btrim(COALESCE(p_ip_hash, '')), ''));

  SELECT w.name, w.slug INTO v_ws_name, v_slug FROM public.workspaces w WHERE w.id = v_ws;
  SELECT s.name INTO v_service_name FROM public.services s WHERE s.id = p_service_id;
  SELECT p.display_name INTO v_pro_name FROM public.professional_profiles p WHERE p.member_id = v_pro;
  SELECT st.business_phone INTO v_phone_biz FROM public.workspace_settings st WHERE st.workspace_id = v_ws;

  RETURN jsonb_build_object(
    'appointment_id', v_id,
    'workspace_name', v_ws_name,
    'slug', v_slug,
    'service_name', v_service_name,
    'professional_name', v_pro_name,
    'starts_at', p_starts_at,
    'ends_at', v_ends,
    'duration_minutes', v_snapshot.duration_minutes,
    'price_cents', v_snapshot.price_cents,
    'timezone', v_tz,
    'status', 'scheduled',
    'business_phone', v_phone_biz,
    'guest', v_uid IS NULL
  );
END;
$function$

CREATE OR REPLACE FUNCTION app.require_confirmed_email()
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_uid uuid;
  v_confirmed timestamptz;
BEGIN
  v_uid := app.require_authenticated_user();
  SELECT u.email_confirmed_at
    INTO v_confirmed
  FROM auth.users u
  WHERE u.id = v_uid;

  IF v_confirmed IS NULL THEN
    RAISE EXCEPTION 'email_not_confirmed'
      USING ERRCODE = '42501';
  END IF;

  RETURN v_uid;
END;
$function$

CREATE OR REPLACE FUNCTION app.require_workspace_manager(p_workspace_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid;
begin
  v_uid := app.require_confirmed_email();
  perform app.assert_workspace_entitled(p_workspace_id);

  if not app.has_workspace_role(
    p_workspace_id,
    variadic array['owner'::public.member_role, 'admin'::public.member_role]
  ) then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  return v_uid;
end;
$function$

CREATE OR REPLACE FUNCTION app.resolve_public_workspace(p_slug text)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_id uuid;
  v_slug text := lower(btrim(coalesce(p_slug, '')));
begin
  if v_slug = '' then
    raise exception 'workspace_not_found' using errcode = '22023';
  end if;

  select w.id into v_id
  from public.workspaces w
  where w.slug = v_slug;

  if v_id is null then
    raise exception 'workspace_not_found' using errcode = '22023';
  end if;

  if not app.workspace_has_entitlement(v_id) then
    raise exception 'workspace_unavailable' using errcode = '22023';
  end if;

  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION app.update_workspace_settings(p_workspace_id uuid, p_name text, p_slug text, p_business_phone text, p_business_email text, p_description text, p_address text, p_city text, p_state text, p_postal_code text, p_instagram text, p_timezone text, p_logo_path text DEFAULT NULL::text, p_clear_logo boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_name text;
  v_slug text;
  v_phone text;
  v_email text;
  v_instagram text;
  v_postal text;
  v_state text;
  v_workspace public.workspaces;
  v_settings public.workspace_settings;
BEGIN
  PERFORM app.require_workspace_manager(p_workspace_id);

  v_name := btrim(p_name);
  IF char_length(v_name) < 2 OR char_length(v_name) > 80 THEN
    RAISE EXCEPTION 'invalid_workspace_name' USING ERRCODE = '22023';
  END IF;

  v_slug := app.slugify(p_slug);
  IF v_slug IS NULL OR char_length(v_slug) < 3 OR char_length(v_slug) > 60 THEN
    RAISE EXCEPTION 'invalid_slug' USING ERRCODE = '22023';
  END IF;
  IF v_slug !~ '^[a-z0-9]+(?:-[a-z0-9]+)*$' THEN
    RAISE EXCEPTION 'invalid_slug' USING ERRCODE = '22023';
  END IF;
  IF app.is_reserved_workspace_slug(v_slug) THEN
    RAISE EXCEPTION 'reserved_slug' USING ERRCODE = '22023';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.workspaces w
    WHERE w.slug = v_slug AND w.id IS DISTINCT FROM p_workspace_id
  ) THEN
    RAISE EXCEPTION 'slug_taken' USING ERRCODE = '23505';
  END IF;

  v_phone := app.normalize_phone(p_business_phone);
  IF p_business_phone IS NOT NULL AND btrim(p_business_phone) <> '' AND v_phone IS NULL THEN
    RAISE EXCEPTION 'invalid_phone' USING ERRCODE = '22023';
  END IF;

  v_email := nullif(lower(btrim(coalesce(p_business_email, ''))), '');
  v_instagram := nullif(btrim(regexp_replace(coalesce(p_instagram, ''), '^@+', '')), '');
  v_postal := regexp_replace(coalesce(p_postal_code, ''), '\D', '', 'g');
  IF v_postal = '' THEN
    v_postal := NULL;
  END IF;
  v_state := nullif(upper(btrim(coalesce(p_state, ''))), '');

  IF p_logo_path IS NOT NULL AND split_part(p_logo_path, '/', 1) IS DISTINCT FROM p_workspace_id::text THEN
    RAISE EXCEPTION 'invalid_logo_path' USING ERRCODE = '22023';
  END IF;

  PERFORM set_config('app.bypass_protected_columns', 'on', true);

  UPDATE public.workspaces
  SET name = v_name,
      slug = v_slug,
      updated_at = clock_timestamp()
  WHERE id = p_workspace_id
  RETURNING * INTO v_workspace;

  UPDATE public.workspace_settings
  SET business_phone = v_phone,
      business_email = v_email,
      description = nullif(btrim(coalesce(p_description, '')), ''),
      address = nullif(btrim(coalesce(p_address, '')), ''),
      city = nullif(btrim(coalesce(p_city, '')), ''),
      state = v_state,
      postal_code = v_postal,
      instagram = v_instagram,
      timezone = coalesce(nullif(btrim(coalesce(p_timezone, '')), ''), 'America/Sao_Paulo'),
      logo_path = CASE
        WHEN p_clear_logo THEN NULL
        WHEN p_logo_path IS NOT NULL THEN p_logo_path
        ELSE logo_path
      END,
      updated_at = clock_timestamp()
  WHERE workspace_id = p_workspace_id
  RETURNING * INTO v_settings;

  RETURN jsonb_build_object(
    'workspace_id', v_workspace.id,
    'name', v_workspace.name,
    'slug', v_workspace.slug,
    'timezone', v_settings.timezone
  );
END;
$function$
